<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api, errorText, type Document, type Grant, type Group, type KnowledgeBase, type User } from '../../shared/api'
const props = defineProps<{ token: string; knowledge: KnowledgeBase[] }>()
const users = ref<User[]>([]), groups = ref<Group[]>([]), audits = ref<{ id: string; action: string; target_id: string; created_at: string }[]>([])
const error = ref(''), busy = ref(false), username = ref(''), password = ref(''), role = ref('user'), usage = ref('demo'), groupName = ref('')
const groupId = ref(''), members = ref<string[]>([]), kbId = ref(''), documents = ref<Document[]>([]), documentId = ref('')
const grant = ref<Grant>({ visibility: 'groups', group_ids: [] }), editUser = ref(''), newPassword = ref('')
async function load() {
  const [u, g, a] = await Promise.all([api<User[]>('/admin/users', props.token), api<Group[]>('/admin/groups', props.token), api<typeof audits.value>('/admin/audit-events', props.token)])
  users.value = u; groups.value = g; audits.value = a
}
async function action(work: () => Promise<unknown>) { busy.value = true; error.value = ''; try { await work(); await load() } catch (reason) { users.value = []; groups.value = []; audits.value = []; error.value = errorText(reason) } finally { busy.value = false } }
async function createUser() { await action(async () => { await api('/admin/users', props.token, { method: 'POST', body: JSON.stringify({ username: username.value, password: password.value, role: role.value, usage_kind: usage.value }) }); username.value = ''; password.value = '' }) }
async function updateUser(user: User, changes: Record<string, unknown>) { await action(() => api(`/admin/users/${user.id}`, props.token, { method: 'PATCH', body: JSON.stringify(changes) })) }
async function resetPassword() { await action(async () => { await api(`/admin/users/${editUser.value}`, props.token, { method: 'PATCH', body: JSON.stringify({ password: newPassword.value }) }); newPassword.value = ''; editUser.value = '' }) }
async function createGroup() { await action(async () => { await api('/admin/groups', props.token, { method: 'POST', body: JSON.stringify({ name: groupName.value }) }); groupName.value = '' }) }
async function saveMembers() { await action(() => api(`/admin/groups/${groupId.value}/members`, props.token, { method: 'PUT', body: JSON.stringify({ user_ids: members.value }) })) }
async function loadDocuments() { documents.value = []; documentId.value = ''; grant.value = { visibility: 'groups', group_ids: [] }; await action(async () => { documents.value = await api<Document[]>(`/documents?kb_id=${encodeURIComponent(kbId.value)}`, props.token) }) }
async function loadGrant() { grant.value = { visibility: 'groups', group_ids: [] }; if (!documentId.value) return; await action(async () => { const rows = await api<Grant[]>(`/admin/documents/${documentId.value}/access`, props.token); grant.value = rows[0]! }) }
async function saveGrant() { await action(() => api(`/admin/documents/${documentId.value}/access`, props.token, { method: 'PUT', body: JSON.stringify({ visibility: grant.value.visibility, group_ids: grant.value.visibility === 'groups' ? grant.value.group_ids : [] }) })) }
onMounted(() => { void action(async () => {}) })
</script>
<template>
  <p v-if="error" class="error" role="alert">{{ error }}</p>
  <section class="panel"><h2>用户管理</h2><form class="inline-form" @submit.prevent="createUser"><input v-model="username" aria-label="新用户名" placeholder="用户名" required maxlength="100"><input v-model="password" aria-label="初始密码" type="password" autocomplete="new-password" placeholder="初始密码（12–72 字节）" required minlength="12" maxlength="72"><select v-model="role" aria-label="角色"><option value="user">成员</option><option value="admin">管理员</option></select><select v-model="usage" aria-label="使用类型"><option value="demo">演示</option><option value="real_usage">真实使用</option></select><button :disabled="busy">创建用户</button></form>
    <ul class="document-list"><li v-for="user in users" :key="user.id"><span>{{ user.username }} · {{ user.role }} · {{ user.disabled ? '已停用' : '正常' }} · {{ user.usage_kind }}</span><div class="actions"><button :disabled="busy" @click="updateUser(user, { disabled: !user.disabled })">{{ user.disabled ? '启用账号' : '停用账号' }}</button><button :disabled="busy" @click="updateUser(user, { usage_kind: user.usage_kind === 'demo' ? 'real_usage' : 'demo' })">切换使用类型</button><button @click="editUser = user.id; newPassword = ''">重设密码</button></div></li></ul>
    <form v-if="editUser" class="inline-form" @submit.prevent="resetPassword"><input v-model="newPassword" aria-label="重设密码" type="password" autocomplete="new-password" required minlength="12" maxlength="72"><button :disabled="busy">保存新密码</button><button type="button" @click="editUser = ''; newPassword = ''">取消</button></form>
  </section>
  <section class="panel"><h2>用户组</h2><form class="inline-form" @submit.prevent="createGroup"><input v-model="groupName" aria-label="用户组名称" placeholder="用户组名称" required maxlength="200"><button :disabled="busy">创建用户组</button></form><label>选择用户组<select v-model="groupId" @change="members = [...(groups.find(g => g.id === groupId)?.user_ids ?? [])]"><option value="">请选择</option><option v-for="group in groups" :key="group.id" :value="group.id">{{ group.name }}</option></select></label><div v-if="groupId"><label v-for="user in users" :key="user.id" class="check"><input v-model="members" type="checkbox" :value="user.id">{{ user.username }}</label><button :disabled="busy" @click="saveMembers">保存组成员</button></div></section>
  <section class="panel"><h2>文档访问范围</h2><label for="access-kb">知识库</label><select id="access-kb" v-model="kbId" @change="loadDocuments"><option value="">请选择</option><option v-for="kb in knowledge" :key="kb.id" :value="kb.id">{{ kb.name }}</option></select><label for="access-document">文档</label><select id="access-document" v-model="documentId" @change="loadGrant"><option value="">请选择</option><option v-for="doc in documents" :key="doc.id" :value="doc.id">{{ doc.title }}</option></select><div v-if="documentId"><select v-model="grant.visibility" aria-label="文档可见范围"><option value="groups">指定用户组（空组仅管理员）</option><option value="all_users">所有用户</option></select><div v-if="grant.visibility === 'groups'"><label v-for="group in groups" :key="group.id" class="check"><input v-model="grant.group_ids" type="checkbox" :value="group.id">{{ group.name }}</label></div><button :disabled="busy" @click="saveGrant">保存访问范围</button></div></section>
  <section class="panel"><h2>权限审计</h2><button :disabled="busy" @click="action(async () => {})">刷新审计</button><ul class="document-list"><li v-for="audit in audits" :key="audit.id"><span>{{ audit.action }} · {{ audit.target_id }}</span><time>{{ new Date(audit.created_at).toLocaleString('zh-CN') }}</time></li></ul></section>
</template>
